    if tool_name not in _TOOLS_WITH_HIDDEN_LLM_COST:
        return 0, 0
    structured = getattr(result, "structuredContent", None) or {}
    return int(structured.get("tokens_in") or 0), int(structured.get("tokens_out") or 0)


